import studio.teja.airbridge.*;
public class BridgeTest{
 static int n;static void check(boolean c,String m){n++;if(!c)throw new AssertionError(m);}
 public static void main(String[] a){
  for(int[] size:new int[][]{{1080,2400},{1272,2800},{2800,1272},{100,100}}){SwipePlan up=new SwipePlan(size[0],size[1],1),down=new SwipePlan(size[0],size[1],-1);check(up.startY>up.endY,"next is upward swipe");check(down.startY<down.endY,"previous is downward swipe");check(up.x>0&&up.x<size[0]&&up.startY<size[1]&&up.endY>0,"within screen");check(up.durationMs==260,"bounded duration");}
  SwipeGate g=new SwipeGate();check(g.request(1,1000).equals("ACCEPT"),"first accepted");check(g.request(2,2000).equals("BUSY"),"no concurrent swipe");g.complete();check(g.request(1,3000).equals("DUPLICATE"),"no duplicate replay");check(g.request(2,3000).equals("DUPLICATE"),"busy command is dropped, not queued");check(g.request(3,3000).equals("ACCEPT"),"fresh command accepted");g.complete();check(g.request(4,3100).equals("COOLDOWN"),"rapid repeats dropped");check(g.request(5,4000).equals("ACCEPT"),"later deliberate gesture accepted");
  SwipePlan comments=new SwipePlan(1272,2800,1,"COMMENTS",false),reading=new SwipePlan(1272,2800,1,"READING",false),reels=new SwipePlan(1272,2800,1,"REELS",false);check(comments.startY-comments.endY<reading.startY-reading.endY,"comments have short scroll");check(reading.startY-reading.endY<reels.startY-reels.endY,"reading step smaller than reel swipe");check(comments.durationMs==300,"comments slower than reel flick");
  check(ControlContext.resolve("PRIMARY","MEDIA").equals("MEDIA_PLAY_PAUSE"),"media pinch plays/pauses");check(ControlContext.resolve("NEXT","MEDIA").equals("VOLUME_UP"),"media tilt changes volume");check(ControlContext.resolve("PREV","NAV").equals("HOME"),"navigation previous maps Home");check(ControlContext.resolve("CONTEXT","REELS").equals("COMMENTS"),"reels context opens comments");check(ControlContext.resolve("CONTEXT","READING").equals("BACK"),"reading context goes Back");check(!ControlContext.allowed("LAUNCH_ARBITRARY_APP"),"no arbitrary command launch");check(ControlContext.allowed("LAUNCH_INSTAGRAM"),"installed app allowlist");
  boolean rejected=false;try{new SwipePlan(0,2400,1);}catch(IllegalArgumentException e){rejected=true;}check(rejected,"invalid geometry rejected");System.out.println(n+" swipe geometry / command gate assertions passed");
 }
}
